\encoding UTF8
\copy (SELECT json_build_object('id', q.id, 'subject', q.subject_area, 'exam', q.exam_type, 'q', q.question_text, 'a', q.option_a, 'b', q.option_b, 'c', q.option_c, 'd', q.option_d, 'e', q.option_e, 'key', q.correct_answer) FROM question_bank q WHERE q.is_active AND q.quality_review_status = 'unverified' AND q.pipeline_metadata::jsonb->>'verified_provisional' = 'true' AND q.correct_answer IN ('A','B','C','D','E') AND q.option_a IS NOT NULL AND q.option_b IS NOT NULL AND q.option_c IS NOT NULL AND q.option_d IS NOT NULL AND q.option_e IS NOT NULL AND q.word_count >= 5 AND q.question_text !~* '^aşağıdaki[a-zçğıöşü ]*hangisi (yanlış|doğru|kesinlikle)\??$' AND (length(q.question_text)-length(replace(q.question_text,'$','')))%2 = 0 AND NOT (q.pipeline_metadata::jsonb ? 'demoted_at') AND ((q.pipeline_metadata::jsonb->>'match_tier') IS NULL OR (q.pipeline_metadata::jsonb->>'match_tier') NOT IN ('tier1_page_inline','tier1b_position_page_inline')) AND ((q.pipeline_metadata::jsonb->'ai_extras'->>'topic_match_quality') IS DISTINCT FROM 'fallback') AND NOT (q.question_text ~* '^yukar(ı|ıdaki)' AND (q.pipeline_metadata::jsonb->'ai_extras'->>'has_diagram')::boolean IS NOT TRUE) AND NOT (q.question_text ~* '^bu (parça|şekil|tablo|grafik|diyalog)' AND (q.pipeline_metadata::jsonb->'ai_extras'->>'has_diagram')::boolean IS NOT TRUE) ORDER BY md5(q.id) LIMIT 300) TO 'C:/Users/husey/kiro2/backend/scripts/quality/_pool_growth_pilot/master.csv' CSV
